#!/usr/bin/env node

/**
 * Block Generated Files Hook (PreToolUse / Edit|Write)
 *
 * Denies edits to files that are regenerated from source.
 * Tells Claude how to regenerate them instead.
 */

import { readFileSync } from 'fs'

let input
try {
  input = JSON.parse(readFileSync(0, 'utf-8'))
} catch {
  process.exit(0)
}

const filePath = input?.tool_input?.file_path

if (!filePath) {
  process.exit(0)
}

const projectDir = process.env.CLAUDE_PROJECT_DIR || ''
const rel = filePath.startsWith(projectDir + '/') ? filePath.slice(projectDir.length + 1) : filePath

const rules = [
  {
    test: (p) => p === 'server/payload-types.ts',
    reason:
      '`server/payload-types.ts` is generated by `pnpm types:cms` (it curls the latest schema from the SahajCloud CMS and strips augmentation). Do not hand-edit it. To change the CMS types, the upstream SahajCloud schema must change; for app-specific types use `server/cms-types.ts`.',
  },
]

const matched = rules.find((r) => r.test(rel))

if (matched) {
  const out = {
    hookSpecificOutput: {
      hookEventName: 'PreToolUse',
      permissionDecision: 'deny',
      permissionDecisionReason: matched.reason,
    },
  }
  console.log(JSON.stringify(out))
  process.exit(0)
}

process.exit(0)
